"""NONSCIENTIFIC CPU-only runner supplied on stdin; no model/data adapters."""
import sys
import os
import builtins
import time
import json
import hashlib
import io
import contextlib
import importlib.metadata
from pathlib import Path

root = Path.cwd().resolve()
selected = sys.argv[2:]
label = sys.argv[1]
allowed_relative = ['pyproject.toml', 'tests/scoring/test_fixtures.py',
    'tests/scoring/test_independent_review.py',
    'docs/design-inputs/unicode-15.1.0/CaseFolding.txt',
    'docs/design-inputs/unicode-15.1.0/PropList.txt']
for directory in ['src/scoring', 'src/acceptance', 'tests/acceptance']:
    allowed_relative += [p.as_posix() for p in Path(directory).glob('*.py')]
allowed = {str(root / p) for p in allowed_relative}
runtime_roots = {str(Path(p).resolve()) for p in [sys.prefix, sys.base_prefix]}
for p in sys.path:
    if p and 'site-packages' in p:
        runtime_roots.add(str(Path(p).resolve()))
denied_roots = {'torch', 'mlx', 'transformers', 'tensorflow', 'jax', 'parakeet'}
blocks = []
reads = set()
started = time.perf_counter()
def forbidden(category):
    blocks.append(category)
    raise AssertionError('NONSCIENTIFIC runner blocked ' + category)
def audit(event, args):
    if event.startswith('socket.') or event in {'subprocess.Popen', 'os.system', 'os.posix_spawn', 'os.fork', 'os.exec'}:
        forbidden('network_or_subprocess')
    if event == 'import':
        name = args[0]
        if name.split('.')[0] in denied_roots or name.startswith(('src.models', 'src.inference', 'benchmarks.')):
            forbidden('neural_or_scientific_import')
    if event == 'open':
        target, mode, flags = args
        if isinstance(target, int):
            return
        if flags & (os.O_WRONLY | os.O_RDWR | os.O_CREAT | os.O_TRUNC | os.O_APPEND):
            forbidden('file_write')
        path = str(Path(os.fsdecode(target)).resolve())
        if path not in allowed and not any(path == p or path.startswith(p + os.sep) for p in runtime_roots):
            forbidden('non_allowlisted_file_read')
        if path.startswith(str(root) + os.sep):
            reads.add(Path(path).relative_to(root).as_posix())
sys.addaudithook(audit)
original_import = builtins.__import__
def guarded_import(name, *args, **kwargs):
    if name.split('.')[0] in denied_roots or name.startswith(('src.models', 'src.inference', 'benchmarks.')):
        forbidden('neural_or_scientific_import')
    return original_import(name, *args, **kwargs)
builtins.__import__ = guarded_import
import numpy as np
import pytest
def no_array_loading(*args, **kwargs):
    forbidden('array_or_checkpoint_loading')
np.load = no_array_loading

class ReceiptPlugin:
    def __init__(self):
        self.nodes = []
        self.counts = {'passed': 0, 'failed': 0, 'skipped': 0, 'errors': 0}
        self.node_outcomes = []
    def pytest_collection_finish(self, session):
        self.nodes = [item.nodeid for item in session.items]
    def pytest_runtest_logreport(self, report):
        if report.when == 'call':
            self.counts[report.outcome] += 1
            self.node_outcomes.append({'node': report.nodeid, 'outcome': report.outcome})
        elif report.failed:
            self.counts['errors'] += 1
        elif report.skipped:
            self.counts['skipped'] += 1
    def pytest_collectreport(self, report):
        if report.failed:
            self.counts['errors'] += 1
plugin = ReceiptPlugin()
arguments = ['-q', '-p', 'no:cacheprovider', '-p', 'no:logging', '--assert=plain', '--capture=sys', '-c', 'pyproject.toml'] + selected
output = io.StringIO()
with contextlib.redirect_stdout(output), contextlib.redirect_stderr(output):
    status = int(pytest.main(arguments, plugins=[plugin]))
loaded_neural = sorted(m for m in sys.modules if m.split('.')[0] in denied_roots or m.startswith(('src.models', 'src.inference')))
result = {'schema_version': 'fixture_projection_test_result_v1', 'provenance': 'NONSCIENTIFIC',
    'label': label, 'selected': selected, 'pytest_arguments': arguments,
    'python_version': sys.version, 'dependency_versions': {n: importlib.metadata.version(n) for n in ['numpy', 'pytest', 'unicodedata2']},
    'source_sha256': {p: hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in sorted(set(allowed_relative))},
    'nodes': plugin.nodes, 'node_outcomes': plugin.node_outcomes,
    'counts': plugin.counts, 'pytest_exit_status': status,
    'elapsed_runner_seconds': time.perf_counter() - started,
    'isolation': {'blocked_events': blocks, 'loaded_neural_modules': loaded_neural,
        'allowed_repository_reads_observed': sorted(reads),
        'network_and_subprocess_audit_hooks': True, 'read_allowlist': sorted(allowed_relative),
        'file_writes_blocked': True, 'neural_imports_blocked': True,
        'numpy_array_loading_blocked': True, 'plugin_autoload_disabled': os.environ.get('PYTEST_DISABLE_PLUGIN_AUTOLOAD') == '1',
        'acceptance_test_body_tripwires': 'Exact accepted synthetic_isolation fixture retained'},
    'output': output.getvalue()}
print(json.dumps(result, sort_keys=True))
sys.exit(status)
